+@inject ILogger<Recipes> Logger
+@inject NavigationManager Navigation
+@implements IDisposable
+
+<PageTitle>Recipes</PageTitle>
+
+<h1>Recipes</h1>
+
+<div class="mb-3">
+    <a href="/recipes/1?sort=@Sort" class="btn btn-outline-primary me-2">Italian</a>
+    <a href="/recipes/2?sort=@Sort" class="btn btn-outline-primary me-2">Thai</a>
+    <a href="/recipes/3?sort=@Sort" class="btn btn-outline-primary">Mexican</a>
+</div>
+
+<div class="mb-3">
+    <label class="form-label fw-bold">Sort by:</label>
+    <a href="/recipes/@CuisineId?sort=newest" class="btn btn-sm @(Sort == "popular" ? "btn-outline-secondary" : "btn-secondary") me-1">Newest</a>
+    <a href="/recipes/@CuisineId?sort=popular" class="btn btn-sm @(Sort == "popular" ? "btn-secondary" : "btn-outline-secondary")">Popular</a>
+</div>
+
+@if (_errorMessage is not null)
+{
+    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
+        <span>@_errorMessage</span>
+        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="Retry">Retry</button>
+    </div>
+}
+else if (_recipes is null)
+{
+    <div class="d-flex align-items-center gap-2 my-4">
+        <div class="spinner-border text-primary" role="status"></div>
+        <span>Loading recipes…</span>
+    </div>
+}
+else
+{
+    @if (_isRefreshing)
+    {
+        <div class="alert alert-info py-1 px-3 d-inline-flex align-items-center gap-2 mb-3">
+            <div class="spinner-border spinner-border-sm" role="status"></div>
+            <span>Refreshing…</span>
+        </div>
+    }
+
+    <div class="row">
+        @foreach (var recipe in GetSortedRecipes())
+        {
+            <div class="col-md-4 mb-3">
+                <div class="card h-100">
+                    <div class="card-body">
+                        <h5 class="card-title">@recipe.Title</h5>
+                        <p class="card-text">@recipe.Description</p>
+                        <span class="badge bg-secondary">@recipe.PrepTimeMinutes min</span>
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+
+    @if (_recipes.Count == 0)
+    {
+        <p class="text-muted">No recipes found for this cuisine.</p>
+    }
+}
+
+@code {
+    [Parameter]
+    public int CuisineId { get; set; }
+
+    [SupplyParameterFromQuery(Name = "sort")]
+    public string? Sort { get; set; }
+
+    private List<Recipe>? _recipes;
+    private bool _isRefreshing;
+    private string? _errorMessage;
+
+    private int _loadedCuisineId;
+    private CancellationTokenSource? _cts;
+
+    protected override async Task OnParametersSetAsync()
+    {
+        NormalizeSort();
+
+        if (CuisineId == _loadedCuisineId && _recipes is not null)
+        {
+            // Sort-only change — no reload needed.
+            return;
+        }
+
+        await LoadRecipesAsync();
+    }
+
+    private async Task LoadRecipesAsync()
+    {
+        // Cancel any in-flight request.
+        await CancelPendingRequestAsync();
+
+        _cts = new CancellationTokenSource();
+        var token = _cts.Token;
+        var targetCuisineId = CuisineId;
+
+        _errorMessage = null;
+        _isRefreshing = _recipes is not null;
+
+        if (!_isRefreshing)
+        {
+            StateHasChanged();
+        }
+
+        try
+        {
+            var result = await RecipeService.GetByCuisineAsync(targetCuisineId, token);
+
+            if (token.IsCancellationRequested)
+            {
+                return;
+            }
+
+            _recipes = result;
+            _loadedCuisineId = targetCuisineId;
+            _isRefreshing = false;
+        }
+        catch (OperationCanceledException) when (token.IsCancellationRequested)
+        {
+            // Request was intentionally cancelled — do nothing.
+        }
+        catch (TimeoutException ex)
+        {
+            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", targetCuisineId);
+            _isRefreshing = false;
+            _errorMessage = "The request timed out. Please try again.";
+        }
+        catch (Exception ex)
+        {
+            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", targetCuisineId);
+            _isRefreshing = false;
+            _errorMessage = "Something went wrong while loading recipes. Please try again.";
+        }
+    }
+
+    private List<Recipe> GetSortedRecipes()
+    {
+        if (_recipes is null)
+        {
+            return new List<Recipe>();
+        }
+
+        return Sort == "popular"
+            ? _recipes.OrderBy(r => r.PrepTimeMinutes).ToList()
+            : _recipes.OrderByDescending(r => r.Id).ToList();
+    }
+
+    private async Task Retry()
+    {
+        _errorMessage = null;
+        _recipes = null;
+        await LoadRecipesAsync();
+    }
+
+    private void NormalizeSort()
+    {
+        if (Sort is not ("newest" or "popular"))
+        {
+            Sort = "newest";
+        }
+    }
+
+    private async Task CancelPendingRequestAsync()
+    {
+        if (_cts is not null)
+        {
+            await _cts.CancelAsync();
+            _cts.Dispose();
+            _cts = null;
+        }
+    }
+
+    public void Dispose()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+        _cts = null;
+    }
+}
+

